// src/utils/html-extractor.ts
function extractSearchData(html) {
  const scriptRegex = /<script[^>]*>([\s\S]*?)<\/script>/g;
  for (const match2 of html.matchAll(scriptRegex)) {
    const scriptContent = match2[1];
    if (scriptContent === undefined)
      continue;
    const content = scriptContent.trim();
    if (content.includes('"__typename":"StaySearchResult"') && content.includes("listingParamOverrides")) {
      const jsonStr = findJsonObject(content, '{"data":{"presentation"');
      if (jsonStr !== null) {
        try {
          const parsed = JSON.parse(jsonStr);
          return {
            searchResults: parsed.data.presentation.staysSearch.results.searchResults
          };
        } catch {}
      }
    }
  }
  return { searchResults: [] };
}
function extractDetailData(html) {
  const scriptRegex = /<script[^>]*>([\s\S]*?)<\/script>/g;
  for (const match2 of html.matchAll(scriptRegex)) {
    const scriptContent = match2[1];
    if (scriptContent === undefined)
      continue;
    const content = scriptContent.trim();
    if ((content.includes('"__typename":"SectionDetail"') || content.includes('"__typename":"SectionContainer"')) && content.includes("stayProductDetailPage")) {
      const jsonStr = findJsonObject(content, '{"data":{"presentation"');
      if (jsonStr !== null) {
        try {
          const parsed = JSON.parse(jsonStr);
          return {
            sections: parsed.data.presentation.stayProductDetailPage.sections.sections,
            metadata: parsed.data.presentation.stayProductDetailPage.sections.metadata
          };
        } catch {}
      }
    }
  }
  return { sections: [], metadata: null };
}
function findJsonObject(content, startMarker) {
  const start = content.indexOf(startMarker);
  if (start < 0)
    return null;
  let depth = 0;
  let inString = false;
  let isEscaped = false;
  let jsonStr = "";
  for (let i = start;i < content.length; i++) {
    const ch = content[i];
    jsonStr += ch;
    if (isEscaped) {
      isEscaped = false;
      continue;
    }
    if (ch === "\\") {
      isEscaped = true;
      continue;
    }
    if (ch === '"' && !inString) {
      inString = true;
      continue;
    }
    if (ch === '"' && inString) {
      inString = false;
      continue;
    }
    if (!inString) {
      if (ch === "{")
        depth++;
      if (ch === "}")
        depth--;
      if (depth === 0 && ch === "}") {
        break;
      }
    }
  }
  return jsonStr;
}

